const p=$json.body ?? $json;
if (!['vllm','codex','antigravity','hermes'].includes(p.backend)) throw new Error('backend must be explicitly vllm, codex, antigravity, or hermes');
if (p.action !== 'cancel' && (typeof p.task !== 'string' || !p.task.trim())) throw new Error('task required');
if (p.action === 'cancel' && !['codex','antigravity'].includes(p.backend)) throw new Error('cancel supported for CLI requests');
const timeout=p.timeout ?? 300;
if (!Number.isFinite(timeout) || timeout<1 || timeout>3600) throw new Error('timeout must be 1..3600 seconds');
const output_mode=p.output_mode ?? 'text';
if (!['text','json'].includes(output_mode)) throw new Error('output_mode must be text or json');
if (p.schema !== undefined && (!p.schema || typeof p.schema!=='object' || Array.isArray(p.schema))) throw new Error('schema must be JSON object');
const q={...p,timeout,output_mode,cwd:p.cwd ?? '/home/core/projects/cloud-infrastructure'};
q.vllm_body={model:q.model ?? 'qwen3.8-27b-fp8',messages:[{role:'user',content:q.task}],max_tokens:q.max_tokens ?? 1024};
if (q.output_mode==='json') q.vllm_body.response_format=q.schema ? {type:'json_schema',json_schema:{name:'edge_result',strict:true,schema:q.schema}} : {type:'json_object'};
return [{json:{...q,payload:Buffer.from(JSON.stringify(q)).toString('base64')}}];

const p=$('Validate Contract').first().json;
let out;
if (['codex','antigravity'].includes(p.backend)) {
 try {out=JSON.parse($json.stdout);} catch {out={ok:false,status:'transport_error',error:$json.error ?? $json.stderr ?? 'Invalid SSH result'};}
} else {
 const r=$json.body ?? $json; const status=$json.statusCode;
 if ($json.error || (status && (status<200 || status>=300)) || r.error) out={ok:false,status:'backend_error',http_status:status ?? null,error:$json.error ?? r.error};
 else {
  let text=p.backend==='vllm' ? r.choices?.[0]?.message?.content : r.output?.flatMap(x=>x.content ?? []).filter(x=>x.type==='output_text').map(x=>x.text).join('\n');
  if (p.backend==='vllm' && r.choices?.[0]?.finish_reason==='length') out={ok:false,status:'token_limit',result:text};
  else if (typeof text!=='string') out={ok:false,status:'invalid_backend_response',result:r};
  else if (p.output_mode==='json') { try {out={ok:true,status:'completed',result:JSON.parse(text),usage:r.usage};} catch {out={ok:false,status:'invalid_json',result:text};} }
  else out={ok:true,status:'completed',result:text,usage:r.usage};
 }
}
return [{json:{backend:p.backend,...out}}];
